14	/**
15	 * The PostgreSQL database every test runs against.
16	 *
17	 * <p>VaadinBench: this environment has no Docker, so instead of a Testcontainers
18	 * {@code postgres:17-alpine} container each Spring context gets a fresh, empty
19	 * database on the local PostgreSQL server ({@code vb-postgres}, started on
20	 * demand). The class keeps its upstream name so that every
21	 * {@code @Import(TestcontainersConfiguration.class)} works unchanged, and it
22	 * behaves the same way: Flyway migrates the new database, the test-only seed in
23	 * {@code src/test/resources/db/migration} fills it, and nothing is shared with
24	 * any other context.
25	 */
26	@TestConfiguration(proxyBeanMethods = false)
27	public class TestcontainersConfiguration {
28	
29	    private static final String SERVER = "jdbc:postgresql://localhost:5432/";
30	    private static final String USER = "postgres";
31	
32	    @Bean
33	    JdbcConnectionDetails postgresConnectionDetails() {
34	        String database = "petclinic_test_" + UUID.randomUUID().toString().replace("-", "");
35	        createDatabase(database);
36	        String url = SERVER + database;
37	        return new JdbcConnectionDetails() {
38	            @Override
39	            public String getUsername() {
40	                return USER;
41	            }
42	
43	            @Override
44	            public String getPassword() {
45	                return "";
46	            }
47	
48	            @Override
49	            public String getJdbcUrl() {
50	                return url;
51	            }
52	        };
53	    }
54	
55	    private static void createDatabase(String database) {
56	        try {
57	            execute("CREATE DATABASE " + database);
58	        } catch (SQLException notRunning) {
59	            startServer();
60	            try {
61	                execute("CREATE DATABASE " + database);
62	            } catch (SQLException e) {
63	                throw new IllegalStateException("PostgreSQL is not reachable on localhost:5432", e);
64	            }
65	        }
66	    }
67	
68	    private static void execute(String sql) throws SQLException {
69	        try (Connection connection = DriverManager.getConnection(SERVER + "postgres", USER, "");
70	             Statement statement = connection.createStatement()) {
71	            statement.execute(sql);
72	        }
73	    }
74	
75	    private static void startServer() {
76	        try {
77	            Process process = new ProcessBuilder("vb-postgres", "start").inheritIO().start();
78	            if (process.waitFor() != 0) {
79	                throw new IllegalStateException("vb-postgres start failed");
80	            }
81	        } catch (IOException e) {
82	            throw new IllegalStateException("vb-postgres is not on the PATH", e);
83	        } catch (InterruptedException e) {
84	            Thread.currentThread().interrupt();
85	            throw new IllegalStateException(e);
86	        }
87	    }
